use xiom.io;

use xiom.string;
fn main() -> Int {
  let inventory: Map[Str,Int] = Map[Str,Int].new();
  inventory.insert("sword", 1);
  inventory.insert("shield", 2);
  inventory.insert("potion", 5);

  if inventory.contains("bow") {
    io.println("bow found");
  }
  else {
    io.println("bow not found");
  }

  match inventory.remove("shield") {
    Some(qty) => io.println("Removed shield x" + to_string(qty));
    None => io.println("shield not found");
  }

  io.println(inventory.contains("shield").to_str());
  return 0;
}
